function handler(params) {
  var associations = params?.data?.var?.associations || {};
  var result = [];

  for (var key in associations) {
    var entry = associations[key];

    // Extract products & product_models safely
    var products =
      entry && entry.products && entry.products.length > 0
        ? entry.products
        : [];

    var models =
      entry && entry.product_models && entry.product_models.length > 0
        ? entry.product_models
        : [];

    // Only push when at least ONE of them has values
    if (products.length > 0 || models.length > 0) {
      result.push({
        association_type: key,
        products: products,
        product_models: models
      });
    }
  }

  return {
    transformedAssociations: result
  };
}

