function handler(params) {
  var association = params?.data?.steps?.SelectAssociationType?.output?.[0] || {};
  var code = association.akeneo_code || "";
  var label = association.label_en || "";

  var rows = params?.data?.steps?.SelectAllProducts?.output || [];

  function toBool(v) {
    if (v === true) return true;
    if (v === false) return false;
    var s = String(v || "").trim().toLowerCase();
    return s === "true" || s === "1" || s === "t" || s === "yes";
  }

  // 1) keep only enabled
  var enabledRows = [];
  for (var i = 0; i < rows.length; i++) {
    var r = rows[i] || {};
    if (toBool(r.enabled)) enabledRows.push(r);
  }

  // 2) group parent!=null into { parent_sku: parent, variants:[...] } else standalone
  var grouped = {}; // parentSku -> { parent_sku, variants: [] }
  var products = [];

  for (var j = 0; j < enabledRows.length; j++) {
    var r2 = enabledRows[j] || {};
    var sku = String(r2.sku || "").trim();
    var parent = r2.parent; // null or string

    if (!sku) continue;

    if (parent === null || parent === undefined || String(parent).trim() === "") {
      products.push({ parent_sku: sku });
      continue;
    }

    var parentSku = String(parent).trim();
    if (!grouped[parentSku]) grouped[parentSku] = { parent_sku: parentSku, variants: [] };
    grouped[parentSku].variants.push(sku);
  }

  for (var p in grouped) products.push(grouped[p]);

  return {
    code,
    label,
    products
  };
}

