function handler(params) {
  const combinedAccessories = params?.data?.var?.accessoriesCombined || [];
  const map = {};

  for (const item of combinedAccessories) {
    if (!item?.code) continue;

    const code = String(item.code);
    if (code.includes("warranty")) continue;

    if (!map[code]) {
      map[code] = {
        code,
        label: item?.label || "",
        products: []
      };
    }

    // append products
    const prods = Array.isArray(item?.products) ? item.products : [];
    map[code].products.push(...prods);
  }

  return { accessories: Object.values(map) };
}

